function mesh(geometry,color,emissive=0){return new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({color,emissive,emissiveIntensity:.6,roughness:.35,metalness:.15}));}
const board=mesh(new THREE.BoxGeometry(21.8,.45,23.8),0x0c142b);board.position.y=-.43;scene.add(board);
const wallGeo=new THREE.BoxGeometry(.92,.58,.92),wallMat=new THREE.MeshStandardMaterial({color:0x1739a4,emissive:0x123bda,emissiveIntensity:.3,metalness:.4,roughness:.3});
const walls=new THREE.InstancedMesh(wallGeo,wallMat,MAP.join('').split('#').length-1),matrix=new THREE.Matrix4();let wi=0;MAP.forEach((row,y)=>[...row].forEach((c,x)=>{if(c==='#'){matrix.makeTranslation(x-10,.1,y-11);walls.setMatrixAt(wi++,matrix);}}));scene.add(walls);
const edges=new THREE.EdgesGeometry(wallGeo);const edgePositions=[];const edgeArray=edges.attributes.position.array;MAP.forEach((row,y)=>[...row].forEach((c,x)=>{if(c==='#')for(let i=0;i<edgeArray.length;i+=3)edgePositions.push(edgeArray[i]+x-10,edgeArray[i+1]+.1,edgeArray[i+2]+y-11);}));const lineGeo=new THREE.BufferGeometry();lineGeo.setAttribute('position',new THREE.Float32BufferAttribute(edgePositions,3));scene.add(new THREE.LineSegments(lineGeo,new THREE.LineBasicMaterial({color:0x527cff,transparent:true,opacity:.74})));
const pelletGeo=new THREE.SphereGeometry(.085,8,6),powerGeo=new THREE.SphereGeometry(.22,16,12),pellets=new Map();function populate(){for(const m of pellets.values())scene.remove(m);pellets.clear();for(const [key,type] of game.pellets){const [x,y]=key.split(',').map(Number);const m=mesh(type==='o'?powerGeo:pelletGeo,0xffeab0,0xffd260);m.position.set(x-10,.17,y-11);scene.add(m);pellets.set(key,m);}}
const pacman=new THREE.Group();const pacMat=new THREE.MeshStandardMaterial({color:0xffe52b,emissive:0xd8a900,emissiveIntensity:.32,roughness:.25});
// Two hemispheres form a sphere whose mouth opens in the direction of travel.
const halfGeo=new THREE.SphereGeometry(.43,28,16,0,Math.PI);const top=new THREE.Mesh(halfGeo,pacMat),bottom=new THREE.Mesh(halfGeo,pacMat);top.rotation.x=-Math.PI/2;bottom.rotation.x=Math.PI/2;const upper=new THREE.Group(),lower=new THREE.Group();upper.add(top);lower.add(bottom);pacman.add(upper,lower);scene.add(pacman);
const ghostColors=[0xff5279,0xffa4df,0x56e3ef,0xffb46b];const ghostMeshes=ghostColors.map(color=>{const group=new THREE.Group();const body=mesh(new THREE.CylinderGeometry(.36,.4,.48,20),color,color);body.position.y=.15;group.add(body);const head=mesh(new THREE.SphereGeometry(.36,20,16),color,color);head.position.y=.38;group.add(head);for(const x of [-.15,.15]){const eye=mesh(new THREE.SphereGeometry(.12,12,8),0xffffff);eye.scale.set(1,1.2,.55);eye.position.set(x,.4,.31);group.add(eye);const pupil=mesh(new THREE.SphereGeometry(.057,10,8),0x121d53);pupil.position.set(x,.4,.38);group.add(pupil);}for(const x of [-.26,0,.26]){const foot=mesh(new THREE.SphereGeometry(.13,10,8),color,color);foot.position.set(x,-.07,0);group.add(foot);}scene.add(group);return group;});
function resize(){const {width,height}=$('stage').getBoundingClientRect();renderer.setSize(width,height,false);const aspect=width/height,halfH=Math.max(12.7,11.7/aspect);camera.left=-halfH*aspect;camera.right=halfH*aspect;camera.top=halfH;camera.bottom=-halfH;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe($('stage'));resize();populate();
let priorState='',priorLevel=1;function sync(){if(game.score>best){best=game.score;try{localStorage.setItem('neon-pacman-best',String(best));}catch{}}$('score').textContent=String(game.score).padStart(6,'0');$('best').textContent=String(best).padStart(6,'0');$('lives').textContent='● '.repeat(game.lives).trim()||'—';$('lives').setAttribute('aria-label',`${game.lives} 條生命`);$('level').textContent=String(game.level).padStart(2,'0');$('power').hidden=game.power<=0;$('power-time').textContent=game.power.toFixed(1);$('pause').disabled=!['playing','paused'].includes(game.state);$('pause').textContent=game.state==='paused'?'▶ 繼續':'Ⅱ 暫停';if(game.state!==priorState){priorState=game.state;const state=game.state;$('overlay').hidden=state==='playing';const labels={ready:['準備開吃？','一座迷宮，無限挑戰。','開始遊戲','PLAYER ONE'],paused:['休息一下','迷宮會等你，幽靈也是。','繼續遊戲','PAUSED'],over:['下次，再高一點。',`本次獲得 ${game.score.toLocaleString()} 分`,'再玩一次','GAME OVER'],won:['完美清盤！',`第 ${game.level} 關完成，準備迎接更快的幽靈。`,'下一關','LEVEL COMPLETE']};if(labels[state]){const [title,description,action,kicker]=labels[state];$('overlay-title').textContent=title;$('overlay-description').textContent=description;$('start').innerHTML=`${action} <span>↗</span>`;$('overlay-kicker').textContent=kicker;$('overlay-hint').textContent=state==='paused'?'按空白鍵繼續':'按 Enter 開始';}$('status').textContent={ready:'準備就緒',playing:'遊戲進行中',paused:'已暫停',over:'遊戲結束',won:'關卡完成'}[state];}}
function start(){const state=game.state;game.start();if(state==='over'||game.level!==priorLevel){populate();priorLevel=game.level;}beep(720,.1);sync();}
$('start').onclick=start;$('pause').onclick=()=>{game.pause();sync();};$('restart').onclick=()=>{game.reset();populate();priorLevel=1;game.start();sync();};$('sound').onclick=()=>{sound=!sound;$('sound').textContent=`音效 ${sound?'開':'關'}`;$('sound').setAttribute('aria-pressed',String(sound));beep();};
const keymap={ArrowUp:'up',w:'up',ArrowDown:'down',s:'down',ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right'};window.addEventListener('keydown',e=>{if(e.target instanceof HTMLButtonElement&&['Enter',' '].includes(e.key))return;const dir=keymap[e.key]||keymap[e.key.toLowerCase()];if(dir){e.preventDefault();game.input(dir);}else if(e.code==='Space'){e.preventDefault();if(!e.repeat){game.pause();sync();}}else if(e.key==='Enter'&&!e.repeat&&game.state!=='playing')start();});document.querySelectorAll('[data-dir]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();game.input(b.dataset.dir);}));let touch;const stage=$('stage');stage.addEventListener('pointerdown',e=>{touch={x:e.clientX,y:e.clientY};});stage.addEventListener('pointerup',e=>{if(!touch)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;if(Math.hypot(dx,dy)>16)game.input(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up');touch=null;});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.state==='playing'){game.pause();sync();}});
let last=performance.now();function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.05);last=now;game.update(dt);for(const event of game.events.splice(0)){if(event.type==='eat'){const m=pellets.get(event.key);scene.remove(m);pellets.delete(event.key);beep(event.power?650:250,.045);}else beep(event.type==='hit'?120:900,.25,'triangle');}const p=game.position(game.player);pacman.position.set(p.x-10,.35,p.y-11);pacman.rotation.y={right:0,left:Math.PI,up:Math.PI/2,down:-Math.PI/2}[game.player.dir];const chomp=game.state==='playing'&&game.player.moving?.12+Math.abs(Math.sin(now*.018))*.35:.18;upper.rotation.z=chomp;lower.rotation.z=-chomp;pacman.visible=game.invincible<=0||game.state!=='playing'||Math.floor(now/100)%2===0;game.ghosts.forEach((g,i)=>{const m=ghostMeshes[i],gp=game.position(g);m.position.set(gp.x-10,.2+Math.sin(now*.004+i)*.055,gp.y-11);const color=game.power>0?(game.power<2&&Math.floor(now/160)%2?0xe8edff:0x3769f6):ghostColors[i];m.children.forEach((part,j)=>{if(j<2||j>=6){part.material.color.setHex(color);part.material.emissive.setHex(color);}});});for(const [key,m] of pellets)if(game.pellets.get(key)==='o')m.scale.setScalar(1+Math.sin(now*.005)*.16);sync();renderer.render(scene,camera);}sync();requestAnimationFrame(frame);
